<template>
  <main class="publish-page">
    <header class="hero"><span class="hero-icon"><i :class="form.infoType === 1 ? 'el-icon-search' : 'el-icon-present'" /></span><div><h1>发布{{ form.infoType === 1 ? '失物' : '招领' }}信息</h1><p>信息越完整，物品匹配和找回的概率越高</p></div></header>
    <el-form ref="form" :model="form" :rules="rules" label-position="top" class="form">
      <section class="form-section"><section-title icon="el-icon-document" title="基本信息" tip="告诉大家这是什么物品" />
        <el-form-item label="信息类型" prop="infoType"><el-radio-group v-model="form.infoType"><el-radio-button :label="1">我丢失了物品</el-radio-button><el-radio-button :label="2">我捡到了物品</el-radio-button></el-radio-group></el-form-item>
        <div class="two-columns"><el-form-item label="物品名称" prop="itemName"><el-input v-model.trim="form.itemName" placeholder="例如：黑色双肩包" maxlength="100" show-word-limit /></el-form-item><el-form-item label="物品分类" prop="categoryId"><el-select v-model="form.categoryId" placeholder="请选择分类" class="full-width"><el-option v-for="item in categories" :key="item.id" :label="item.categoryName" :value="item.id" /></el-select></el-form-item></div>
        <div class="two-columns"><el-form-item label="颜色"><el-input v-model.trim="form.itemColor" placeholder="例如：黑色、银灰色" /></el-form-item><el-form-item label="品牌或标识"><el-input v-model.trim="form.itemBrand" placeholder="例如：Apple、无品牌" /></el-form-item></div>
      </section>
      <section class="form-section"><section-title icon="el-icon-location-outline" title="时间与地点" tip="帮助缩小寻找范围" /><div class="two-columns"><el-form-item label="发生地点" prop="occurPlace"><el-input v-model.trim="form.occurPlace" placeholder="例如：图书馆三楼自习区" /></el-form-item><el-form-item label="发生时间" prop="occurDate"><el-date-picker v-model="form.occurDate" type="datetime" value-format="yyyy-MM-dd HH:mm:ss" placeholder="选择日期和时间" class="full-width" /></el-form-item></div></section>
      <section class="form-section"><section-title icon="el-icon-picture-outline" title="图片与特征" tip="首张图片自动作为封面，支持拖动排序" />
        <el-form-item label="物品图片"><img-upload v-model="form.itemImages" :limit="6" /><small>最多上传 6 张清晰图片，建议包含整体、细节和独有标识。</small></el-form-item>
        <el-form-item label="显著特征"><el-input v-model="form.itemFeatures" type="textarea" :rows="3" placeholder="例如：右侧有划痕、挂有蓝色钥匙扣、内有姓名贴等可核验特征" maxlength="500" show-word-limit /></el-form-item>
        <el-form-item label="详细描述" prop="description"><el-input v-model="form.description" type="textarea" :rows="5" placeholder="请描述事情经过、物品状态及其他有助于辨认的信息" maxlength="1000" show-word-limit /></el-form-item>
      </section>
      <section class="form-section"><section-title icon="el-icon-phone-outline" title="联系与交接" tip="联系方式在公开详情页脱敏展示" />
        <div class="two-columns"><el-form-item label="联系人" prop="contactName"><el-input v-model.trim="form.contactName" placeholder="请输入联系人姓名" /></el-form-item><el-form-item label="联系电话" prop="contactPhone"><el-input v-model.trim="form.contactPhone" placeholder="请输入手机号码" maxlength="20" /></el-form-item></div>
        <el-form-item label="其他联系方式"><el-input v-model.trim="form.contactMethod" placeholder="例如：微信 campus2026、QQ 12345678" /></el-form-item>
        <el-form-item :label="form.infoType === 2 ? '认领方式' : '归还方式'"><el-input v-model="form.claimMethod" type="textarea" :rows="3" :placeholder="form.infoType === 2 ? '例如：请携带能证明物品归属的信息到学生服务中心认领' : '例如：请联系我当面归还，也可交至保卫处'" /></el-form-item>
      </section>
      <div class="submit-bar"><div><strong>提交后将进入审核</strong><p>请确认信息真实、联系方式有效</p></div><el-button type="primary" :loading="submitting" @click="submit">提交审核</el-button></div>
    </el-form>
  </main>
</template>
<script>
import ImgUpload from '@/components/ImgUpload'
import { clientPublishLostFound } from '@/api/client-user'
import { listPublicCategories } from '@/api/public'
const SectionTitle = { functional: true, props: ['icon', 'title', 'tip'], render(h, ctx) { return h('div', { class: 'section-title' }, [h('i', { class: ctx.props.icon }), h('div', [h('h2', ctx.props.title), h('p', ctx.props.tip)])]) } }
const base = type => ({ infoType: type, itemName: '', categoryId: '', occurPlace: '', occurDate: '', coverImage: '', itemImages: '', itemColor: '', itemBrand: '', itemFeatures: '', description: '', contactName: '', contactPhone: '', contactMethod: '', claimMethod: '' })
export default { name: 'ClientPublish', components: { ImgUpload, SectionTitle }, data() { const type = Number(this.$route.query.type) === 2 ? 2 : 1; return { form: base(type), categories: [], submitting: false, rules: { itemName: [{ required: true, message: '请输入物品名称', trigger: 'blur' }], categoryId: [{ required: true, message: '请选择物品分类', trigger: 'change' }], occurPlace: [{ required: true, message: '请输入发生地点', trigger: 'blur' }], occurDate: [{ required: true, message: '请选择发生时间', trigger: 'change' }], description: [{ required: true, message: '请填写详细描述', trigger: 'blur' }], contactName: [{ required: true, message: '请输入联系人', trigger: 'blur' }], contactPhone: [{ required: true, message: '请输入联系电话', trigger: 'blur' }] } } }, created() { this.loadCategories() }, methods: { async loadCategories() { const res = await listPublicCategories(); this.categories = res.data || [] }, submit() { this.$refs.form.validate(async valid => { if (!valid) return; this.submitting = true; try { this.form.coverImage = (this.form.itemImages || '').split(',').filter(Boolean)[0] || ''; await clientPublishLostFound(this.form); this.$message.success('提交成功，请等待管理员审核'); this.$router.push('/user/my-publish') } finally { this.submitting = false } }) } } }
</script>
<style scoped>.publish-page{max-width:980px;margin:0 auto;padding:34px 20px 60px}.hero{display:flex;align-items:center;gap:18px;margin-bottom:24px}.hero-icon{display:flex;width:58px;height:58px;align-items:center;justify-content:center;border-radius:18px;color:#fff;background:linear-gradient(135deg,#315f91,#5b91c5);font-size:26px;box-shadow:0 10px 24px rgba(49,95,145,.22)}.hero h1{margin:0;color:#20364d;font-size:29px}.hero p{margin:7px 0 0;color:#8192a4}.form{overflow:hidden;border:1px solid #dde7f0;border-radius:18px;background:#f7fafc;box-shadow:0 12px 35px rgba(36,65,95,.08)}.form-section{padding:25px 30px;border-bottom:1px solid #e7edf3;background:#fff}.section-title{display:flex;align-items:center;gap:12px;margin-bottom:20px}.section-title>i{display:flex;width:38px;height:38px;align-items:center;justify-content:center;border-radius:11px;color:#386c9f;background:#eaf3fb;font-size:18px}.section-title h2{margin:0;color:#273f57;font-size:18px}.section-title p{margin:4px 0 0;color:#95a3b2;font-size:12px}.two-columns{display:grid;grid-template-columns:1fr 1fr;gap:22px}.full-width{width:100%}.form small{display:block;margin-top:8px;color:#8c9cad}.submit-bar{display:flex;align-items:center;justify-content:space-between;padding:22px 30px;background:#f7fafc}.submit-bar strong{color:#334e68}.submit-bar p{margin:5px 0 0;color:#91a0af;font-size:12px}.submit-bar .el-button{min-width:140px}@media(max-width:700px){.two-columns{grid-template-columns:1fr;gap:0}.form-section{padding:22px 18px}.submit-bar{gap:16px;padding:20px 18px}.submit-bar .el-button{min-width:110px}}</style>
